package org.apache.commons.math.geometry;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.apache.commons.math3.exception.NotImplementedException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class Vector3D_distance1_TriageGen0Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testDistance1_SamePoint() {
        Vector3D v1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D v2 = new Vector3D(1.0, 2.0, 3.0);
        double expected = 0.0;
        double actual = Vector3D.distance1(v1, v2);
        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_PositiveDifferences() {
        Vector3D v1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D v2 = new Vector3D(1.0, 2.0, 3.0);
        // |1-0| + |2-0| + |3-0| = 6.0
        double expected = 6.0;
        double actual = Vector3D.distance1(v1, v2);
        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_NegativeDifferences() {
        Vector3D v1 = new Vector3D(5.0, 5.0, 5.0);
        Vector3D v2 = new Vector3D(2.0, 8.0, 1.0);
        // |2-5| + |8-5| + |1-5| = |-3| + |3| + |-4| = 3 + 3 + 4 = 10.0
        double expected = 10.0;
        double actual = Vector3D.distance1(v1, v2);
        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_MixedCoordinates() {
        Vector3D v1 = new Vector3D(-1.0, -1.0, -1.0);
        Vector3D v2 = new Vector3D(1.0, 1.0, 1.0);
        // |1 - (-1)| + |1 - (-1)| + |1 - (-1)| = 2 + 2 + 2 = 6.0
        double expected = 6.0;
        double actual = Vector3D.distance1(v1, v2);
        assertEquals(expected, actual, EPSILON);
    }

    @Test
    public void testDistance1_LargeValues() {
        Vector3D v1 = new Vector3D(1e10, 1e10, 1e10);
        Vector3D v2 = new Vector3D(2e10, 2e10, 2e10);
        // |2e10 - 1e10| * 3 = 3e10
        double expected = 3e10;
        double actual = Vector3D.distance1(v1, v2);
        assertEquals(expected, actual, 1.0); // Larger epsilon for large values
    }

    @Test
    public void testDistance1_ZeroComponents() {
        Vector3D v1 = new Vector3D(0.0, 0.0, 0.0);
        Vector3D v2 = new Vector3D(0.0, 0.0, 0.0);
        double expected = 0.0;
        double actual = Vector3D.distance1(v1, v2);
        assertEquals(expected, actual, EPSILON);
    }
}
